      "card_ids": ["C23"],
      "claim": "In healthy adults, R-desethyloxybutynin oral bioavailability was 62 (16)%, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Betaxolol absolute bioavailability after a 20 mg oral dose was 82.3 ± 6.0% versus IV in 12 subjects, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "In young healthy subjects, S-9780 bioavailability after oral perindopril was 19% ± 7%, below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most high-transferability numeric records report oral bioavailability values clearly above 20%, supporting a high prediction. One high-transferability record reports 19%, just below the threshold, but the weight of consistent positive numeric evidence supports high bioavailability.",
  "evidence_gaps": [
    "One high-transferability record reports 19% ± 7%, just below the 20% threshold, creating threshold-adjacent conflict.",
    "Some records are qualitative or from special populations such as cirrhosis, elderly, or uraemic patients and were not used as primary numeric evidence.",
    "Molecule 3 provides only qualitative 'good' bioavailability without a numeric F value."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

